import flax.linen as nn
import jax
import jax.numpy as jnp
from jax import random
import optax

NUM_NEURONS = 71721
INPUT_HORIZON = 4
OUTPUT_HORIZON = 32

# NEW: Simple MLP Gating on Global Mean
class GlobalMlpGatingNetwork(nn.Module):
    num_experts: int
    @nn.compact
    def __call__(self, x):
        # x shape: (B, T_in, N)
        # Create a simple global summary
        gater_input = jnp.mean(x, axis=(1, 2)) # Shape: (B,)
        gater_input = jnp.expand_dims(gater_input, axis=-1) # Shape: (B, 1)

        y = nn.Dense(features=32)(gater_input)
        y = nn.relu(y)
        logits = nn.Dense(features=self.num_experts)(y)
        return nn.softmax(logits, axis=-1)

# ... (Rest of the MoFL code is identical to ID 285, omitting for brevity)
def mae_with_temporal_curvature(predictions, targets, lam=1e-4):
    mae = jnp.mean(jnp.abs(predictions - targets))
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]
    curv_pen = jnp.mean(curv * curv)
    return mae + lam * curv_pen

class ResidualCopyHead(nn.Module):
    @nn.compact
    def __call__(self, x):
        num_neurons = x.shape[2]; x_flat = x.transpose(0, 2, 1).reshape(-1, 4); residual = nn.Dense(64)(x_flat); residual = nn.relu(residual); residual = nn.Dense(32)(residual); residual = residual.reshape(x.shape[0], num_neurons, 32).transpose(0, 2, 1); output = jnp.zeros((x.shape[0], 32, num_neurons)); output = output.at[:, :4, :].set(x); final_output = output + residual; return final_output

class MoFL_Model_Simple_Gater(nn.Module):
    num_experts: int; rank_k: int; proj_rank: int; mlp_hidden_size: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, training: bool = False):
        B, T_in, N = x.shape; k, p, E = self.rank_k, self.proj_rank, self.num_experts
        gate_weights = GlobalMlpGatingNetwork(num_experts=E, name="gating")(x)
        U_experts = self.param('U_experts', nn.initializers.lecun_normal(), (E, N, p)); V_experts = self.param('V_experts', nn.initializers.lecun_normal(), (E, k, p))
        U_batch = jnp.einsum('be,enp->bnp', gate_weights, U_experts); V_batch = jnp.einsum('be,ekp->bkp', gate_weights, V_experts)
        U_batch = U_batch / (jnp.linalg.norm(U_batch, axis=1, keepdims=True) + 1e-6)
        xU = jnp.einsum('btn,bnp->btp', x, U_batch); factors_in = jnp.einsum('btp,bkp->btk', xU, V_batch)
        factors_flat = factors_in.reshape((B, -1)); h = nn.Dense(self.mlp_hidden_size)(factors_flat); h = nn.relu(h); h = nn.Dropout(rate=self.dropout_rate, deterministic=not training)(h); h = nn.Dense(self.mlp_hidden_size)(h); h = nn.relu(h); h = nn.Dropout(rate=self.dropout_rate, deterministic=not training)(h)
        factors_out_flat = nn.Dense(OUTPUT_HORIZON * k)(h); factors_out = factors_out_flat.reshape((B, OUTPUT_HORIZON, k)); factors_out_norm = nn.LayerNorm()(factors_out)
        z = jnp.einsum('btk,bkp->btp', factors_out_norm, V_batch); y_factor = jnp.einsum('btp,bnp->btn', z, U_batch)
        y_copy = ResidualCopyHead()(x); return y_factor + y_copy

class ModelWrapper:
    def __init__(self, hparams):
        self.model = MoFL_Model_Simple_Gater(**hparams); self.needs_rng = True
    def init(self, rng_key, dummy_input):
        rngs = {'params': rng_key, 'dropout': rng_key}; return self.model.init(rngs, dummy_input, training=True)
    def apply(self, params, x, training=False, mutable=None, rngs=None):
        if rngs and 'dropout' in rngs and rngs['dropout'] is not None:
            return self.model.apply(params, x, training=training, rngs={'dropout': rngs['dropout']})
        else:
            return self.model.apply(params, x, training=training)

def _define_hyperparameters():
    return { 'learning_rate': 0.001, 'weight_decay': 1e-4, 'gradient_clip': 1.0, 'num_experts': 4, 'rank_k': 320, 'proj_rank': 32, 'mlp_hidden_size': 512, 'dropout_rate': 0.1 }

def create_network(hparams):
    model_params = {k: hparams.get(k) for k in ['num_experts', 'rank_k', 'proj_rank', 'mlp_hidden_size', 'dropout_rate']}; return ModelWrapper(hparams=model_params)

def compute_loss(predictions, targets, params, x):
    return mae_with_temporal_curvature(predictions, targets)

def create_optimizer(learning_rate: float = 0.001):
    hparams = _define_hyperparameters(); return optax.chain( optax.clip_by_global_norm(hparams.get('gradient_clip')), optax.adamw(learning_rate=learning_rate, weight_decay=hparams.get('weight_decay')) )
